<script setup lang="ts">import {ref,computed,watch} from 'vue';import {fixed} from '../utils/format';import SobolBars from './SobolBars.vue';const props=defineProps<{result:any}>();const stages=computed<any[]>(()=>props.result.sobol_stages||[]);const progress=computed<any>(()=>props.result.sobol_progress||null);const choice=computed(()=>stages.value.find(s=>s.power===selected.value)||stages.value[stages.value.length-1]);const selected=ref<number|null>(null);watch(stages,s=>{if(s.length&&!s.some(item=>item.power===selected.value))selected.value=s[s.length-1].power},{immediate:true});const rows=computed<any[]>(()=>choice.value?choice.value.indices:[]);const low=computed(()=>Math.min(0,...rows.value.flatMap((r:any)=>[r.s1,r.st]))),high=computed(()=>Math.max(1,...rows.value.flatMap((r:any)=>[r.s1,r.st])));const X=(v:number)=>90+(v-low.value)/(high.value-low.value)*330;</script><template><section v-if="stages.length" class="sobol-stages"><div class="section-heading"><h2>Sobol 分档</h2><label>基础样本档<select v-model.number="selected"><option v-for="s in stages" :key="s.power" :value="s.power">n={{s.base_samples}} · m={{s.power}} · 累计{{s.cumulative_evaluations}}次</option></select></label></div><p v-if="progress" class="stage-status"><span>已完成 {{progress.completed_stages}} / {{progress.expected_stages}} 档</span><span v-if="progress.complete">全部档位完成，可提交复核</span><span v-else-if="progress.failed_power!==null">失败于m={{progress.failed_power}}，可从最近完成m={{progress.last_completed_power??'无'}}恢复</span><span v-else>下一档 m={{progress.resume_from_power}}</span></p><div v-if="choice" class="table-wrap"><table><thead><tr><th>因子</th><th>S1</th><th>ST</th><th>ST−S1</th><th>ST排名 / 变化</th><th>较上档 ΔS1</th><th>较上档 ΔST</th><th>较上档 Δ(ST−S1)</th></tr></thead><tbody><tr v-for="r in rows" :key="r.factor_id"><td><b>{{r.factor_id}}</b><small v-if="r.prev_power===null">首档，无上档对照</small></td><td>{{fixed(r.s1,5)}}</td><td>{{fixed(r.st,5)}}</td><td>{{fixed(r.gap,5)}}</td><td>{{r.st_rank}}<small v-if="r.prev_st_rank!==null">上档排名 {{r.prev_st_rank}} · {{r.st_rank_change===0?"持平":(r.st_rank_change>0?"↑"+r.st_rank_change:"↓"+(-r.st_rank_change))}}</small><small v-else>首档</small></td><td>{{r.delta_s1===null?'—':fixed(r.delta_s1,5)}}</td><td>{{r.delta_st===null?'—':fixed(r.delta_st,5)}}</td><td>{{r.delta_gap===null?'—':fixed(r.delta_gap,5)}}</td></tr></tbody></table></div><SobolBars :rows="rows"/></section></template>
